   <script>
     const quizForm = document.querySelector("#quiz-form");
     const result = document.querySelector("#result");

     quizForm.addEventListener("submit", (event) => {
       event.preventDefault();

       const checkedAnswers = quizForm.querySelectorAll("input[type='checkbox']:checked").length;
       result.textContent = checkedAnswers === 1
         ? "You selected 1 answer."
         : `You selected ${checkedAnswers} answers.`;
     });
   </script>
 </body>
 </html>

')
